        do {
            var todayStats = try context.fetchTodayStats()
            if todayStats == nil {
                todayStats = DailyStats(date: Date())
                context.insert(todayStats!)
            }
            todayStats!.phonePickups = todayPickups

            try context.save()
        } catch {
            #if DEBUG
